head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.ckb1 = "N";
scwin.ckb2 = "N";
scwin.ckb3 = "N";
scwin.ckb4 = "N";
scwin.ckb5 = "N";
scwin.ckb6 = "N";
scwin.ckb7 = "N";
scwin.ckb8 = "N";
scwin.ckb9 = "N";
scwin.ckb10 = "N";
scwin.ckb11 = "N";

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name ins_search
 * @description 삭제 내역 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_search = async function() {
    // 코드삭제일 체크
    if ($c.stf.compareFromToDate2(edt_SDEL_DD, edt_EDEL_DD) === false) {
        return false;
    }
    scwin.setCheckBox();

    //     alert( url);
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name setCheckBox
 * @description CHECKB 박스 값을 정의한다.
 * @returns {void}
 * @hidden N
 */
scwin.setCheckBox = function() {
    /*ckb1주권1 ckb_2채권  ckb_3ELS/DLS ckb_4수익증권 ckb_5 신주인수권증권 ckb_6유가증권예탁증서(DR)
		ckb_7전자단기사채/CP ckb_8스트립 ckb_9양도성예금증서(CD) ckb_10주식워런트증권(ELW)    ckb_11 ETN     ckb_12 투자계약증권
     */
    scwin.ckb1 = ckb_1.getValue();
    scwin.ckb2 = ckb_2.getValue();
    scwin.ckb3 = ckb_3.getValue();
    scwin.ckb4 = ckb_4.getValue();
    scwin.ckb5 = ckb_5.getValue();
    scwin.ckb6 = ckb_6.getValue();
    scwin.ckb7 = ckb_7.getValue();
    scwin.ckb8 = ckb_8.getValue();
    scwin.ckb9 = ckb_9.getValue();
    scwin.ckb10 = ckb_10.getValue();
    scwin.ckb11 = ckb_11.getValue();
    ckb12 = ckb_12.getValue();
};

/**
 * @method
 * @name chkValid
 * @description 조회 조건을 체크한다..... 체크박스는 한개이상 서택하여야 한다.
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    scwin.ckb1 = ckb_1.getValue();
    scwin.ckb2 = ckb_2.getValue();
    scwin.ckb3 = ckb_3.getValue();
    scwin.ckb4 = ckb_4.getValue();
    scwin.ckb5 = ckb_5.getValue();
    scwin.ckb6 = ckb_6.getValue();
    scwin.ckb7 = ckb_7.getValue();
    scwin.ckb8 = ckb_8.getValue();
    scwin.ckb9 = ckb_9.getValue();
    scwin.ckb10 = ckb_10.getValue();
    scwin.ckb11 = ckb_11.getValue();
    ckb12 = ckb_12.getValue();
    if (scwin.ckb1 === "N" &&
        scwin.ckb2 === "N" &&
        scwin.ckb3 === "N" &&
        scwin.ckb4 === "N" &&
        scwin.ckb5 === "N" &&
        scwin.ckb6 === "N" &&
        scwin.ckb7 === "N" &&
        scwin.ckb8 === "N" &&
        scwin.ckb9 === "N" &&
        scwin.ckb10 === "N" &&
        scwin.ckb11 === "N" &&
        ckb12 === "N") {
        return false;
    }
};
scwin.arrPar = new Array();

/**
 * @method
 * @name getParam
 * @description 전달 값을 정의한다.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue(); // ISUR_APPL_ID
    scwin.arrPar[1] = ""; // R 신청

    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    scwin.arrPar, length;
};

/**
 * @method
 * @name setDefaultVal
 * @description 화면의 기본값 세팅
 * @returns {void}
 * @hidden N
 */
scwin.setDefaultVal = function() {
    $c.stf.setFromToDate(3, edt_SDEL_DD, edt_EDEL_DD);
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.setDefaultVal();
    txb_param1.hide();
    txb_STD_CD.focus();
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_search_onclick = async function() {
    if (scwin.chkValid() === false) {
        await $c.win.alert("조회할 유가증권을 선택하세요.");
        return;
    }
    await scwin.ins_search();
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    if (dts_List.errorMsg) {
        await $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }

};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    await $c.win.alert(dts_List);

};

/**
 * @method
 * @name img_SDEL_DD_onclick
 * @description img_SDEL_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_SDEL_DD_onclick = function() {
    popUpCalendar2(edt_SDEL_DD);
};

/**
 * @method
 * @name img_EDEL_DD_onclick
 * @description img_EDEL_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_EDEL_DD_onclick = function() {
    popUpCalendar2(edt_EDEL_DD);
};

/**
 * @method
 * @name txb_STD_CD_onkeyup
 * @description txb_STD_CD 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_STD_CD_onkeyup = async function() {
    fn_DelChar3(this);
    if (txb_STD_CD.getValue() === "") {

    } else {
        if (window.event.keyCode === 13) {
            if (scwin.chkValid() === false) {
                await $c.win.alert("조회할 유가증권을 선택하세요.");
                return;
            } else {
                await scwin.ins_search();
            }
        } else {

        }
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = async function() {
    fn_DelChar3(this);
    if (txb_ISUR_CD.getValue() === "") {

    } else {
        if (window.event.keyCode === 13) {
            if (scwin.chkValid() === false) {
                await $c.win.alert("조회할 유가증권을 선택하세요.");
                return;
            } else {
                await scwin.ins_search();
            }
        } else {

        }
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    let DEL_DD = dts_List.getCellData(row, "DEL_DD");
    DEL_DD = DEL_DD.replace("-", "");
    DEL_DD = DEL_DD.replace("-", "");
    // alert("DEL_DD " +DEL_DD);
    if (DEL_DD < "20140101") return; // asis 상품은 상세팝업 제공 안함
    if (row === 0) return;
    const KND = dts_List.getCellData(row, "KND");
    const STD_CD = dts_List.getCellData(row, "STD_CD");
    if (KND === "지표" || KND === "선물옵션" || KND === "스트립") {
        txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    } else {
        txb_param1.setValue(dts_List.getCellData(row, "STD_CD"));
    }
    fn_GetPar = scwin.getParam;
    ins_ViewIsuMaster(KND, STD_CD);
};
